{-# LANGUAGE BangPatterns #-}
{-# LANGUAGE DeriveTraversable #-}
{-# LANGUAGE LambdaCase #-}
{-# LANGUAGE MonoLocalBinds #-}
-- | hegg port of benchmarks/matmul-assoc/matmul-assoc-<n>.egg (matrix-chain associativity,
-- from foresight's examples/mm; generated by benchmarks/matmul-assoc/gen.py).
--
-- A chain of n multiplications Mul(...Mul(Mul(Mat, Mat), Mat)..., Mat), the two
-- associativity rules, run to saturation: iterations until one adds no e-node and merges
-- nothing (that final no-op iteration counts, as it does in egglog's (saturate (run))).
-- (Mat 10 10) is the only matrix and its arguments are always 10, 10, so it is a nullary
-- leaf here (egglog's i64 literals are not counted as e-nodes either way). Trivial @()@
-- analysis, no scheduler, no node/time limit, no extraction.
--
-- The driver loop is the one of the math-microbenchmark port (hegg's own
-- 'runEqualitySaturation' caps iterations at 30 and bans rules through its scheduler):
-- per iteration build the relational database over canonical e-class ids, 'ematch' every
-- rule against it, apply every match (represent the right-hand side and 'merge'), then
-- 'rebuild' once. The e-graph is a persistent value, so every match of an iteration is
-- found in the e-graph as it was at the start of it.
--
-- Usage: matmul-assoc [--instance N]      (default 20)
-- Prints @iterations N@, @run_s <seconds>@ and the e-nodes per constructor (egglog names,
-- (print-size) format) on stdout; details on stderr.
module Main (main) where

import Control.Exception (evaluate)
import Control.Monad.Trans.State.Strict (State, runState, state)
import Data.Foldable (foldl')
import qualified Data.IntMap.Strict as IM
import qualified Data.IntSet as IS
import qualified Data.Map.Strict as M
import qualified Data.Set as S
import GHC.Clock (getMonotonicTime)
import System.Environment (getArgs)
import System.IO (hPutStrLn, stderr)
import Text.Printf (hPrintf, printf)

import Data.Equality.Graph (ClassId, ENode (..), add, canonicalize, children, emptyEGraph, find,
                            merge, operator, rebuild, represent)
import Data.Equality.Graph.Classes (EClass (..))
import Data.Equality.Graph.Internal (EGraph (..))
import Data.Equality.Graph.Nodes (NodeMap (..), sizeNM)
import Data.Equality.Matching (Match (..), Pattern (..), ematch)
import Data.Equality.Matching.Database (Database (..), IntTrie (..), Subst)
import Data.Equality.Saturation.Rewrites (Rewrite (..))
import Data.Equality.Utils (Fix (..))
import Data.Equality.Utils.SizedList (toListSL)

-- * The language: egglog's Linalg datatype in base-functor form

data Linalg a
  = Mat          -- (Mat 10 10): the only matrix in the program
  | Mul a a
  deriving (Eq, Ord, Show, Functor, Foldable, Traversable)

-- | egglog constructor name of an e-node.
ctor :: Linalg a -> String
ctor = \case
  Mat -> "Mat"; Mul{} -> "Mul"

type G = EGraph () Linalg

-- * The 2 rewrites

type P = Pattern Linalg

-- Pattern variables are ints; hegg numbers the internal variables of a compiled query
-- from 0, so user variables must not collide with small numbers.
x, y, z :: P
x = VariablePattern 101
y = VariablePattern 102
z = VariablePattern 103

mul' :: P -> P -> P
mul' p q = NonVariablePattern (Mul p q)

rules :: [Rewrite () Linalg]
rules =
  [ mul' (mul' x y) z := mul' x (mul' y z)                   -- mul-associativity1
  , mul' x (mul' y z) := mul' (mul' x y) z                   -- mul-associativity2
  ]

-- * The start term, exactly as gen.py builds it

type T = Fix Linalg

-- | Mul(...Mul(Mul(Mat, Mat), Mat)..., Mat) with n Muls.
chain :: Int -> T
chain cnt = iterate (\e -> Fix (Mul e (Fix Mat))) (Fix Mat) !! cnt

-- * One iteration: match all rules, apply all matches, rebuild

-- | The relational database hegg's 'ematch' runs on, built from the canonical e-nodes of
-- every e-class. hegg's own 'Data.Equality.Matching.eGraphToDatabase' builds it from the
-- hashcons without canonicalizing the e-class ids stored there (its "ROMES:TODO map
-- find"); 'rebuild' leaves those ids stale after cascading merges, so a join between two
-- atoms of a pattern can fail on a stale id and matches go missing. Same fold, same
-- tries, canonical ids.
canonicalDatabase :: G -> Database Linalg
canonicalDatabase egr = IM.foldlWithKey' addClass (DB M.empty) (classes egr)
  where
    addClass db cid cls =
      let !cid' = find cid egr
       in S.foldl' (\d nd -> addNode cid' (canonicalize nd egr) d) db (eClassNodes cls)
    addNode cid enode (DB m) = DB (M.alter (Just . populate (cid : children enode)) (operator enode) m)
    populate [] Nothing = MkIntTrie IS.empty IM.empty
    populate (v : vs) Nothing = MkIntTrie (IS.singleton v) (IM.singleton v (populate vs Nothing))
    populate [] (Just t) = t
    populate (v : vs) (Just (MkIntTrie ks m)) = MkIntTrie (IS.insert v ks) (IM.alter (Just . populate vs) v m)

-- | One iteration. Returns whether it changed the e-graph (added an e-node or merged two
-- distinct e-classes), the number of matches applied and the rebuilt e-graph.
--
-- The change test looks at the e-graph after the matches were applied and before the
-- rebuild: hegg's 'add' of a node already in the hashcons and 'merge' of two ids with the
-- same root both return the e-graph untouched, so the hashcons grew iff some e-node was
-- new, and the number of e-classes moved iff some merge or add happened. After a rebuild
-- every e-node's canonical form is in the hashcons, so in an iteration without merges
-- an "added" e-node is really new; that is exactly egglog's no-change test.
step :: [Rewrite () Linalg] -> G -> (Bool, Int, G)
step rws egr0 =
  let db = canonicalDatabase egr0
      -- hegg's e-matching, on the database of the e-graph at the start of the iteration
      matches = [ (rhs, m) | lhs := rhs <- rws, m <- ematch db lhs ]
      (!cnt, !egr1) = foldl' (\(!i, !e) (rhs, Match subst cls) -> (i + 1, applyMatch rhs subst cls e))
                             (0 :: Int, egr0) matches
      changed = sizeNM (memo egr1) /= sizeNM (memo egr0) || IM.size (classes egr1) /= IM.size (classes egr0)
   in (changed, cnt, rebuild egr1)

-- | Apply one match of a rule with right-hand side @rhs@ (as hegg's driver does): a
-- variable right-hand side merges two existing e-classes, otherwise the instantiated
-- right-hand side is added and merged with the e-class the left-hand side matched in.
applyMatch :: P -> Subst -> ClassId -> G -> G
applyMatch (VariablePattern v) subst cls e = snd (merge (substLookup v subst) cls e)
applyMatch (NonVariablePattern p) subst cls e =
  let (cls', e') = reprPat subst p e in snd (merge cls cls' e')

reprPat :: Subst -> Linalg P -> G -> (ClassId, G)
reprPat subst p e0 =
  let (p', e1) = runState (traverse go p) e0 in add (Node p') e1
  where
    go :: P -> State G ClassId
    go (VariablePattern v) = pure (substLookup v subst)
    go (NonVariablePattern q) = state (reprPat subst q)

substLookup :: Int -> Subst -> ClassId
substLookup v = IM.findWithDefault (error "unbound pattern variable") v

-- | Walk every e-class, e-node, parent and hashcons entry, so that no deferred work (a
-- thunk such as a `find` inside a canonicalized child that a map comparison never had
-- to look at) is left to be done outside the timed region or deferred to a later
-- iteration.
forceGraph :: G -> Int
forceGraph egr = fromClasses + fromMemo
  where
    fromClasses = IM.foldlWithKey' (\acc cid cls ->
                    acc + find cid egr
                        + S.foldl' (\s nd -> s + childSum nd) 0 (eClassNodes cls)
                        + foldl' (\s (p, nd) -> s + p + childSum nd) 0 (toListSL (eClassParents cls)))
                  0 (classes egr)
    fromMemo = M.foldlWithKey' (\acc nd cid -> acc + cid + childSum nd) 0 (unNodeMap (memo egr))
    childSum (Node nd) = foldl' (+) 0 nd

-- | Canonical, deduplicated e-nodes of the final e-graph, per constructor. hegg keeps
-- stale (non-canonical) e-nodes in the e-class node sets and in the hashcons, so both
-- are canonicalized and deduplicated first; the two counts must agree.
sizes :: G -> (M.Map String Int, Int)
sizes egr = (M.fromListWith (+) [ (ctor (unNode nd), 1) | nd <- S.toList fromClasses ], S.size fromMemo)
  where
    fromClasses = S.fromList [ canonicalize nd egr | cls <- IM.elems (classes egr), nd <- S.toList (eClassNodes cls) ]
    fromMemo = S.fromList [ canonicalize nd egr | nd <- M.keys (unNodeMap (memo egr)) ]

main :: IO ()
main = do
  args <- getArgs
  let instance' = case args of
        [] -> 20
        ["--instance", s] -> read s
        _ -> error ("usage: matmul-assoc [--instance N], got " ++ show args)

  -- the start term, with invariants restored (as egg's port does)
  let egr0 = rebuild (snd (represent (chain instance') emptyEGraph))
  _ <- evaluate (forceGraph egr0)

  -- iterate until an iteration changes nothing; that iteration counts
  let loop :: Int -> G -> [Int] -> IO (Int, G, [Int])
      loop !i e ms = do
        let (changed, cnt, e') = step rules e
        _ <- evaluate (forceGraph e')
        if changed then loop (i + 1) e' (cnt : ms) else return (i + 1, e', reverse (cnt : ms))
  t0 <- getMonotonicTime
  (iters, egr, matchCounts) <- loop 0 egr0 []
  t1 <- getMonotonicTime
  let runS = t1 - t0

  let (perCtor, memoNodes) = sizes egr
      nodes = sum (M.elems perCtor)
      nClasses = IM.size (classes egr)
  printf "iterations %d\n" iters
  printf "run_s %.6f\n" runS
  putStrLn "("
  mapM_ (\(name, c) -> printf " (%s %d)\n" name c) (M.toList perCtor)
  putStrLn ")"
  hPrintf stderr "hegg: matmul-assoc-%d: %d iterations, %d e-nodes (%d via hashcons), %d e-classes, %.3fs\n"
    instance' iters nodes memoNodes nClasses runS
  hPutStrLn stderr ("hegg: matches applied per iteration " ++ show matchCounts)
